import * as T from 'three';
export const chuteNames={stowed:'収納',armed:'安全条件待ち',reefed:'縮帆展開',open:'全開',landed:'着地',cut:'切離し済み'};
export function parachuteStep(state,{altitude,speed,vertical,density,landed},dt){if(state.status==='cut'){state.fraction=0;return;}if(landed&&state.fraction>0){state.status='landed';state.fraction=0;return;}if(state.status==='armed'&&altitude<5000&&vertical<0&&speed<250&&density>.03&&.5*density*speed*speed<35000)state.status='reefed';if(state.status==='reefed'&&altitude<1500&&speed<80)state.status='open';const target=state.status==='open'?1:state.status==='reefed'?.08:0;state.fraction+=T.MathUtils.clamp(target-state.fraction,-dt/3,dt/3);}
export function parachuteDrag(velocity,density,area,fraction,mass,dt){const speed=velocity.length();if(!speed||!fraction)return new T.Vector3();const force=Math.min(.5*density*speed*speed*area*1.5*fraction,mass*speed/(Math.max(dt,1e-6)*2));return velocity.clone().multiplyScalar(-force/speed);}
